function swotNotes(opts){
  opts=opts||{};
  var topic=(opts.topic||'项目').trim()||'项目';
  function items(s){ return String(s||'').split(/[\n,，;；]+/).map(function(x){return x.trim();}).filter(Boolean); }
  var groups=[['优势 Strengths', items(opts.strengths)],
              ['劣势 Weaknesses', items(opts.weaknesses)],
              ['机会 Opportunities', items(opts.opportunities)],
              ['威胁 Threats', items(opts.threats)]];
  var L=['# SWOT 分析 · '+topic,''];
  for(var g=0;g<groups.length;g++){
    L.push('## '+groups[g][0]);
    var arr=groups[g][1];
    if(arr.length){ for(var i=0;i<arr.length;i++) L.push('- '+arr[i]); }
    else { L.push('- （待补充）'); }
    L.push('');
  }
  return L.join('\n').replace(/\n+$/,'');
}

var EXPORTS={swotNotes:swotNotes};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SwotForgePure = EXPORTS; }
